#!/usr/bin/env python3
"""汎用Huffman処理から頻出深さの定数版を生成し、実装と境界検査の差異を防ぐ。"""

from pathlib import Path


def main() -> None:
    """深さ6〜11の表参照を定数shift・固定長配列にしたGo実装を出力する。"""
    root = Path(__file__).resolve().parents[1]
    source = (root / "internal/zstddecode/huffman_four.go").read_text(encoding="utf-8")
    signature = "func decodeHuffmanFourGeneric(data, out [4][]byte, table []huffmanCell, depth int) error {"
    template = source[source.index(signature):]
    parts = [
        "// Code generated by tools/generate-zstd-huffman.py; DO NOT EDIT.\n"
        "// 頻出するHuffman表の深さを定数化し、可変shiftと反復中の表境界検査を省く。\n"
        "package zstddecode\n\n"
    ]
    for depth in range(6, 12):
        fixed = template.replace(
            signature,
            f"func decodeHuffmanFourDepth{depth}(data, out [4][]byte, table *[{1 << depth}]huffmanCell) error {{\n"
            f"\tconst depth = {depth}",
            1,
        )
        fixed = fixed.replace("out[i], table, depth", "out[i], table[:], depth")
        fixed = fixed.replace("out[i][common:], table, depth", "out[i][common:], table[:], depth")
        parts.append(
            f"// decodeHuffmanFourDepth{depth} は深さ{depth}の表を固定長で参照する。\n"
            + fixed
            + "\n"
        )
    (root / "internal/zstddecode/huffman_fixed.go").write_text(
        "".join(parts).rstrip() + "\n", encoding="utf-8"
    )


if __name__ == "__main__":
    main()
